def split_on_tables(md):
    parts=[]; cur=[]; in_table=False; tc=0
    for line in md.splitlines(True):
        is_table=line.lstrip().startswith('|')
        if is_table and not in_table:
            tc+=1
            if tc>1:
                parts.append(''.join(cur).strip()); cur=[]; tc=1
            in_table=True
        if (not is_table) and in_table: in_table=False
        cur.append(line)
    if cur: parts.append(''.join(cur).strip())
    return [p for p in parts if p]
